package com.shopsphere.controller; import com.shopsphere.dto.AuthDtos.PaymentResponse; import com.shopsphere.service.PaymentService; import org.springframework.security.core.Authentication; import org.springframework.web.bind.annotation.*; import java.util.*; @RestController @RequestMapping("/api/v1/payments") public class PaymentController {private final PaymentService s;public PaymentController(PaymentService s){this.s=s;} @PostMapping("/orders/{orderId}") public PaymentResponse create(Authentication a,@PathVariable UUID orderId){return s.create(orderId,a);} @PostMapping("/{reference}/confirm") public PaymentResponse confirm(@PathVariable String reference){return s.confirm(reference);}}